use rmcp::ErrorData;
/// The `echo` tool.  A basic tool that returns the prompt unchanged
use rmcp::model::{CallToolRequestParams, CallToolResponse, CallToolResult, ContentBlock, Tool};
use rmcp::service::{MaybeSendFuture, RequestContext, RoleServer};
pub(crate) fn new() -> Tool {
    Tool::new(
        "mcp_echo",
        "Echo the provided text back verbatim. Served over MCP.",
        serde_json::json!({
            "type": "object",
            "properties": {
            "text": { "type": "string", "description": "Text to echo" }
            },
            "required": ["text"]
        })
        .as_object()
        .expect("static schema is an object")
        .clone(),
    )
}

pub(crate) fn call<'a>(
    request: CallToolRequestParams,
    _context: RequestContext<RoleServer>,
) -> impl Future<Output = Result<CallToolResponse, ErrorData>> + MaybeSendFuture + 'a {
    let text = request
        .arguments
        .clone()
        .and_then(|mut args| args.remove("text"))
        .and_then(|value| value.as_str().map(String::from))
        .unwrap_or_default();
    let ret = std::future::ready(Ok(CallToolResponse::from(CallToolResult::success(vec![
        ContentBlock::text(text),
    ]))));
    ret.clone()
}

use rmcp::{RoleServer, model::CallToolRequestParams, service::RequestContext};

//use rmcp::ErrorData;
// use rmcp::model::{CallToolRequestParams, CallToolResponse, };
// use rmcp::service::{MaybeSendFuture, RequestContext, RoleServer};

pub trait HanihiTool: std::fmt::Debug {
    fn make_call<'a>(
        &self,
        _request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Box<dyn Fn() -> usize>;
}
//     ) -> Fn(CallToolRequestParams, RequestContext<RoleServer>,) -> impl Future<Output = Result<CallToolResponse, ErrorData>> + MaybeSendFuture + 'a ;
// }

//! Minimal MCP stdio server exposing one `echo` tool.
//!
//! Used to exercise the harness end-to-end:
//! `hanihi-cli --mcp-command ./target/debug/mcp-echo-server`

use hanihi_core::debug;
use rmcp::ErrorData;
use rmcp::handler::server::ServerHandler;
use rmcp::model::{
    CallToolRequestParams, CallToolResponse, ListToolsResult, PaginatedRequestParams,
};
use rmcp::service::{MaybeSendFuture, RequestContext, RoleServer, ServiceExt};
use rmcp::transport;
use std::future::Future;
mod echo_tool;
/// Echo server: replies with the `text` argument verbatim.
#[derive(Debug, Clone, Default)]
struct McpServer;

impl ServerHandler for McpServer {
    fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<ListToolsResult, ErrorData>> + MaybeSendFuture + '_ {
        std::future::ready(Ok(ListToolsResult::with_all_items(vec![echo_tool::new()])))
    }

    fn call_tool(
        &self,
        request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<CallToolResponse, ErrorData>> + MaybeSendFuture + '_ {
        debug::log_to_file("mcp-serve call_tool: name", &request.name);
        let request = request.clone();
        echo_tool::call(request, _context)
    }
}

/// Errors from the echo server binary.
#[derive(Debug)]
enum ServerError {
    /// Protocol initialization failed.
    Init(Box<rmcp::service::ServerInitializeError>),
    /// The service task failed.
    Join(Box<tokio::task::JoinError>),
}

impl std::fmt::Display for ServerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ServerError::Init(e) => write!(f, "server init failed: {e}"),
            ServerError::Join(e) => write!(f, "server task failed: {e}"),
        }
    }
}

impl std::error::Error for ServerError {}

impl From<rmcp::service::ServerInitializeError> for ServerError {
    fn from(e: rmcp::service::ServerInitializeError) -> Self {
        ServerError::Init(Box::new(e))
    }
}

impl From<tokio::task::JoinError> for ServerError {
    fn from(e: tokio::task::JoinError) -> Self {
        ServerError::Join(Box::new(e))
    }
}

#[tokio::main]
async fn main() -> Result<(), ServerError> {
    let service = McpServer.serve(transport::stdio()).await?;
    let _reason = service.waiting().await?;
    Ok(())
}

//! Built-in tools for the agent.
//!
//! Tools are rig [`PortableDynamicTool`]s: name + description + JSON schema +
//! an async callback taking raw `serde_json::Value` arguments.

use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use chrono::Utc;
use grep_regex::{RegexMatcher, RegexMatcherBuilder};
use grep_searcher::{Searcher, Sink, SinkMatch};
use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;
use tokio::io::AsyncReadExt as _;

use crate::source::{SourceError, SourceTree};

/// Map a [`SourceError`] onto a rig tool error with the right kind.
pub(crate) fn map_source_err(e: SourceError) -> ToolExecutionError {
    match e {
        SourceError::NotFound(p) => {
            ToolExecutionError::not_found(format!("no such path: {}", p.display()))
        }
        SourceError::Ignored(p) => {
            ToolExecutionError::permission_denied(format!("path is git-ignored: {}", p.display()))
        }
        SourceError::Escape(p) => ToolExecutionError::permission_denied(format!(
            "path escapes the repository: {}",
            p.display()
        )),
        other => ToolExecutionError::provider(other.to_string()),
    }
}

/// Tool: report the current local date and time.
pub fn builtin_get_time() -> PortableDynamicTool {
    PortableDynamicTool::new(
        "get_time",
        "Get the current local date and time in RFC 3339 format.",
        json!({
            "type": "object",
            "properties": {}
        }),
        |_args: serde_json::Value| {
            Box::pin(async move {
                let now = chrono::Local::now().to_rfc3339();
                Ok(ToolOutput::text(now))
            })
        },
    )
}

/// Tool: read a text file from the git repository.
pub fn builtin_read_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "read_file",
        "Read a text file from the git repository. `path` is relative to the repo root. \
	 Git-ignored paths cannot be read. Returns up to 64 KiB.",
        json!({
            "type": "object",
            "properties": {
            "path": { "type": "string", "description": "Path relative to the repo root" }
            },
            "required": ["path"]
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let rel = args.get("path").and_then(|v| v.as_str()).ok_or_else(|| {
                    ToolExecutionError::invalid_args("missing string field 'path'")
                })?;
                tree.read(Path::new(rel))
                    .map(ToolOutput::text)
                    .map_err(map_source_err)
            })
        },
    )
}

/// Tool: list files and directories in the git repository.
pub fn builtin_list_dir(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "list_dir",
        "List files and directories in the git repository. `path` is relative to the repo root \
	 (default: the root itself). `depth` controls recursion (default 1, max 4). \
	 Git-ignored paths are never listed. One line per entry: type + path.",
        json!({
            "type": "object",
            "properties": {
            "path": { "type": "string", "description": "Directory relative to repo root" },
            "depth": { "type": "integer", "description": "Recursion depth (1-4)" }
            }
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let rel = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
                let depth = args
                    .get("depth")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(1)
                    .clamp(1, 4) as usize;
                let walk = tree.walk(Path::new(rel), depth).map_err(map_source_err)?;
                let mut lines = Vec::new();
                for entry in walk {
                    let entry = entry.map_err(|e| ToolExecutionError::provider(e.to_string()))?;
                    if entry.depth() == 0 {
                        continue;
                    }
                    let ty = match entry.file_type() {
                        Some(t) if t.is_dir() => "dir ",
                        Some(t) if t.is_file() => "file",
                        Some(t) if t.is_symlink() => "link",
                        _ => "oth ",
                    };
                    let p = entry
                        .path()
                        .strip_prefix(tree.root())
                        .unwrap_or(entry.path());
                    lines.push(format!("{ty} {}", p.display()));
                }
                Ok(ToolOutput::text(lines.join("\n")))
            })
        },
    )
}

// ── run_command ──────────────────────────────────────────────────

/// Default timeout for `run_command`.
const DEFAULT_TIMEOUT_SECS: u64 = 120;
/// Maximum allowed timeout for `run_command`.
const MAX_TIMEOUT_SECS: u64 = 600;

/// Per-process sequence number for trace filenames. The tool cannot see the
/// session turn number, so unix-ms + a per-process counter disambiguates
/// traces within a session directory.
static TRACE_SEQ: AtomicU64 = AtomicU64::new(0);

/// Result of executing a command (spawn, wait, capture, timeout).
struct CommandOutcome {
    exit_code: Option<i32>,
    timed_out: bool,
    duration_ms: u64,
    stdout: String,
    stderr: String,
}

/// Validate a whitespace-split command against the allowlist.
