    "man",
    "more",
    "mount",
    "netstat",
    "nl",
    "nm",
    "nslookup",
    "objdump",
    "od",
    "paste",
    "ping",
    "pr",
    "printenv",
    "printf",
    "ps",
    "pwd",
    "readelf",
    "readlink",
    "realpath",
    "rev",
    "sed",
    "seq",
    "sort",
    "ss",
    "stat",
    "strings",
    "tac",
    "tail",
    "test",
    "top",
    "tracepath",
    "traceroute",
    "tree",
    "tr",
    "true",
    "type",
    "uname",
    "uniq",
    "uptime",
