            .is_err()
        );
    }

    #[test]
    fn cap_output_truncates_at_limit() {
        let big = "x".repeat(crate::source::MAX_READ_BYTES + 4096);
        let out = cap_output(&big);
        assert!(out.contains("[truncated"), "got: {out}");
        assert!(out.len() < big.len());
    }

    #[tokio::test]
    async fn execute_captured_times_out_and_kills_child() {
        let cwd = std::env::temp_dir();
        let outcome = execute_captured(&argv(&["sleep", "30"]), &cwd, Duration::from_secs(1))
            .await
            .expect("sleep runs");
        assert!(outcome.timed_out, "expected a timeout");
        assert_eq!(outcome.exit_code, None);
        assert!(outcome.duration_ms >= 1000);
    }

    /// A real git repository (with an initial commit) for command tests.
    fn git_repo() -> PathBuf {
        let dir = std::env::temp_dir().join(format!("hanihi-cmd-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(dir.join("src")).unwrap();
        std::fs::write(
            dir.join("Cargo.toml"),
            "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(dir.join("src/main.rs"), "fn main() {}\n").unwrap();
        let git = |args: &[&str]| {
            std::process::Command::new("git")
                .args(args)
                .current_dir(&dir)
                .output()
                .expect("git runs")
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@example.com"]);
        git(&["config", "user.name", "t"]);
        git(&["add", "-A"]);
        git(&["commit", "-q", "-m", "init"]);
        dir
    }

    #[tokio::test]
    async fn run_command_tool_runs_git_and_writes_trace() {
        let repo = git_repo();
        let tree = Arc::new(SourceTree::open_at(&repo).expect("open repo"));
        let traces_dir = repo.join("traces");
        let tool = builtin_run_command(tree, traces_dir.clone());

        let out = tool
            .execute(serde_json::json!({ "command": "git status --short" }))
            .await
            .expect("git status succeeds")
            .render();
        assert!(out.contains("exit code: 0"), "got: {out}");
        assert!(out.contains("trace:"), "got: {out}");

        // A trace file was written.
        let mut found = false;
        for entry in std::fs::read_dir(&traces_dir).expect("traces dir") {
            let entry = entry.unwrap();
            if entry.file_name().to_string_lossy().ends_with(".cmd.json") {
                let raw = std::fs::read_to_string(entry.path()).unwrap();
                assert!(raw.contains("\"command\": \"git status --short\""));
                found = true;
            }
        }
        assert!(found, "expected a trace file in {}", traces_dir.display());
        std::fs::remove_dir_all(&repo).unwrap_or(());
    }

    #[tokio::test]
    async fn run_command_tool_denies_disallowed_command() {
        let repo = git_repo();
        let tree = Arc::new(SourceTree::open_at(&repo).expect("open repo"));
        let tool = builtin_run_command(tree, repo.join("traces"));

        let err = tool
            .execute(serde_json::json!({ "command": "git push origin main" }))
            .await
            .expect_err("git push must be denied");
        assert!(err.to_string().contains("not allowed"), "got: {err}");
        std::fs::remove_dir_all(&repo).unwrap_or(());
    }
}

//! Minimal MCP stdio server exposing one `echo` tool.
//!
//! Used to exercise the harness end-to-end:
//! `hanihi-cli --mcp-command ./target/debug/mcp-echo-server`

use hanihi_core::debug;
use rmcp::ErrorData;
use rmcp::handler::server::ServerHandler;
use rmcp::model::{
    CallToolRequestParams, CallToolResponse, ListToolsResult, PaginatedRequestParams,
};
use rmcp::service::{MaybeSendFuture, RequestContext, RoleServer, ServiceExt};
use rmcp::transport;
use std::future::Future;
mod echo_tool;
/// Echo server: replies with the `text` argument verbatim.
#[derive(Debug, Clone, Default)]
struct McpServer;

impl ServerHandler for McpServer {
    fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<ListToolsResult, ErrorData>> + MaybeSendFuture + '_ {
        std::future::ready(Ok(ListToolsResult::with_all_items(vec![echo_tool::new()])))
    }

    fn call_tool(
        &self,
        request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<CallToolResponse, ErrorData>> + MaybeSendFuture + '_ {
        debug::log_to_file("mcp-serve call_tool: name", &request.name);
        let request = request.clone();
        echo_tool::call(request, _context)
    }
}

/// Errors from the echo server binary.
#[derive(Debug)]
enum ServerError {
    /// Protocol initialization failed.
    Init(Box<rmcp::service::ServerInitializeError>),
    /// The service task failed.
    Join(Box<tokio::task::JoinError>),
}

impl std::fmt::Display for ServerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ServerError::Init(e) => write!(f, "server init failed: {e}"),
            ServerError::Join(e) => write!(f, "server task failed: {e}"),
        }
    }
}

impl std::error::Error for ServerError {}

impl From<rmcp::service::ServerInitializeError> for ServerError {
    fn from(e: rmcp::service::ServerInitializeError) -> Self {
        ServerError::Init(Box::new(e))
    }
}

impl From<tokio::task::JoinError> for ServerError {
    fn from(e: tokio::task::JoinError) -> Self {
        ServerError::Join(Box::new(e))
    }
}

#[tokio::main]
async fn main() -> Result<(), ServerError> {
    let service = McpServer.serve(transport::stdio()).await?;
    let _reason = service.waiting().await?;
    Ok(())
}

use rmcp::ErrorData;
/// The `echo` tool.  A basic tool that returns the prompt unchanged
use rmcp::model::{CallToolRequestParams, CallToolResponse, CallToolResult, ContentBlock, Tool};
use rmcp::service::{MaybeSendFuture, RequestContext, RoleServer};
pub(crate) fn new() -> Tool {
    Tool::new(
        "mcp_echo",
        "Echo the provided text back verbatim. Served over MCP.",
        serde_json::json!({
            "type": "object",
            "properties": {
            "text": { "type": "string", "description": "Text to echo" }
            },
            "required": ["text"]
        })
        .as_object()
        .expect("static schema is an object")
        .clone(),
    )
}

pub(crate) fn call<'a>(
    request: CallToolRequestParams,
    _context: RequestContext<RoleServer>,
) -> impl Future<Output = Result<CallToolResponse, ErrorData>> + MaybeSendFuture + 'a {
    let text = request
        .arguments
        .clone()
        .and_then(|mut args| args.remove("text"))
        .and_then(|value| value.as_str().map(String::from))
        .unwrap_or_default();
    let ret = std::future::ready(Ok(CallToolResponse::from(CallToolResult::success(vec![
        ContentBlock::text(text),
    ]))));
    ret.clone()
}

