//! Write-path tools: `apply_patch` and `write_file`.
//!
//! These are registered **only** when the CLI is invoked with `--write`.
//! They are scoped to the enclosing git repository via [`SourceTree`]:
//! escapes, git-ignored paths, `.ignore`, and anything under `.git/` are
//! refused. Changes land as local git commits — never pushed. Git is the
//! undo button and the audit trail.

use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;

use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;

use crate::debug;
use crate::source::SourceTree;
use crate::tool::{map_source_err, scrubbed_env};

/// Paths the agent may never write, relative to the repo root.
fn is_protected(rel: &str) -> bool {
    rel == ".ignore" || rel == ".gitignore" || rel.starts_with(".git/") || rel == ".git"
}

/// Run `git` with `args` in `root`, with the scrubbed environment, capturing
/// output. Returns `Ok((stdout, stderr))` on success, `Err(message)` on
/// failure (the more informative of stdout/stderr, trimmed).
///
/// Used only for `git add`/`git commit` after a patch is applied; the
/// unreliable `git apply` machinery is deliberately not used.
async fn git_run(root: &Path, args: &[&str]) -> Result<(String, String), String> {
    let mut cmd = tokio::process::Command::new("git");
    cmd.current_dir(root);
    cmd.env_clear();
    for (k, v) in scrubbed_env() {
        cmd.env(k, v);
    }
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.args(args);
    let output = cmd
        .output()
        .await
        .map_err(|e| format!("spawn git {}: {e}", args[0]))?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
    if !output.status.success() {
        let msg = if stderr.trim().is_empty() {
            stdout.trim()
        } else {
            stderr.trim()
        };
        return Err(msg.to_string());
    }
    Ok((stdout, stderr))
}

/// A single body line of a unified-diff hunk.
#[derive(Debug, Clone, PartialEq, Eq)]
enum BodyLine {
    Context(String),
    Del(String),
    Add(String),
}

impl BodyLine {
    fn text(&self) -> &str {
        match self {
            BodyLine::Context(s) | BodyLine::Del(s) | BodyLine::Add(s) => s,
        }
    }

    fn is_del(&self) -> bool {
        matches!(self, BodyLine::Del(_))
    }

    fn is_add(&self) -> bool {
        matches!(self, BodyLine::Add(_))
    }
}

/// One hunk of a file patch. The `@@` counts are parsed but deliberately
/// ignored: line counts are recomputed from the body (the `--recount`
/// behaviour of `git apply`), so hand-composed hunks with slightly off
/// numbers still apply.
#[derive(Debug)]
struct Hunk {
    lines: Vec<BodyLine>,
}

/// A single file touched by a unified diff.
#[derive(Debug)]
struct FilePatch {
    old_path: Option<String>,
    new_path: Option<String>,
    is_new: bool,
    is_delete: bool,
    hunks: Vec<Hunk>,
}

impl FilePatch {
    /// Repo-relative path this patch writes to.
    fn target_rel(&self) -> Result<String, String> {
        match (&self.old_path, &self.new_path) {
            (_, Some(new)) => Ok(new.clone()),
            (Some(old), None) => Ok(old.clone()),
            (None, None) => Err("file patch has neither an old nor a new path".into()),
        }
    }

    /// The same patch with additions and deletions swapped. Applying the
    /// reverse of an already-applied patch succeeds exactly when the change
    /// is present in the working tree.
    #[cfg(test)]
    fn reversed(&self) -> FilePatch {
        FilePatch {
            old_path: self.new_path.clone(),
            new_path: self.old_path.clone(),
            is_new: self.is_delete,
            is_delete: self.is_new,
            hunks: self
                .hunks
                .iter()
                .map(|h| Hunk {
                    lines: h
                        .lines
                        .iter()
                        .map(|l| match l {
                            BodyLine::Context(s) => BodyLine::Context(s.clone()),
                            BodyLine::Del(s) => BodyLine::Add(s.clone()),
                            BodyLine::Add(s) => BodyLine::Del(s.clone()),
                        })
                        .collect(),
                })
                .collect(),
        }
    }
}

/// Result of applying one file patch, before anything is written.
struct AppliedFile {
    abs: PathBuf,
    /// `None` means the file is to be deleted.
    content: Option<String>,
}

fn is_file_marker(a: &str, b: &str) -> bool {
    (a.starts_with("--- /dev/null") || a.starts_with("--- a/")) && b.starts_with("+++ ")
}

/// Split `diff` into per-file blocks. Each block starts at a `--- ` marker
/// line whose following line is `+++ `, and runs to just before the next
/// such pair (or the end of the input).
fn file_blocks(lines: &[&str]) -> Vec<(usize, usize)> {
    let mut blocks = Vec::new();
    let mut i = 0;
    while i + 1 < lines.len() {
        if is_file_marker(lines[i], lines[i + 1]) {
            let start = i;
            let mut j = i + 2;
            while j < lines.len() {
                if j + 1 < lines.len() && is_file_marker(lines[j], lines[j + 1]) {
                    break;
                }
                j += 1;
            }
            blocks.push((start, j));
            i = j;
        } else {
            i += 1;
        }
    }
    blocks
}

/// Parse the path from a `--- ` or `+++ ` marker line. Returns `None` for
/// `/dev/null` (the "file did not exist" side) and strips git's standard
/// `a/`/`b/` prefixes plus any trailing tab metadata.
fn parse_side_path(marker: &str) -> Option<String> {
    let rest = marker.split('\t').next().unwrap_or(marker).trim();
    if rest == "/dev/null" {
        return None;
    }
    let rel = rest
        .strip_prefix("a/")
        .or_else(|| rest.strip_prefix("b/"))
        .unwrap_or(rest);
    Some(rel.to_string())
}

/// Parse a unified diff into per-file patches. Header lines that carry no
/// content (`index`, `new file mode`, `old/new mode`, `similarity index`,
/// ...) are skipped; binary and rename/copy patches are refused.
fn parse_diff(diff: &str) -> Result<Vec<FilePatch>, String> {
    let lines: Vec<&str> = diff.lines().collect();
    let blocks = file_blocks(&lines);
    if blocks.is_empty() {
        debug::log_to_file("apply_patch on non-diff", diff);
        return Err("no `---`/`+++` file markers found".into());
    }

    let mut patches = Vec::with_capacity(blocks.len());
    for (start, end) in blocks {
        let old_path = parse_side_path(&lines[start]["--- ".len()..]);
        let new_path = parse_side_path(&lines[start + 1]["+++ ".len()..]);
        let mut patch = FilePatch {
            is_new: old_path.is_none(),
            is_delete: new_path.is_none(),
            old_path,
            new_path,
            hunks: Vec::new(),
        };

        let mut i = start + 2;
        while i < end {
            let line = lines[i];
            if let Some(rest) = line.strip_prefix("@@") {
                if !rest.contains("@@") {
                    debug::log_to_file("apply_patch bad hunk header", diff);
                    return Err(format!("malformed hunk header: @@{rest}"));
                }
                i += 1;
                let mut body = Vec::new();
                while i < end && !lines[i].starts_with("@@") {
                    let l = lines[i];
                    if l.starts_with('\\') {
                        // "\ No newline at end of file" — line-level
                        // application does not need it; skip.
                        i += 1;
                        continue;
                    }
                    body.push(parse_body_line(l)?);
                    i += 1;
                }
                patch.hunks.push(Hunk { lines: body });
                continue;
            }
            if line.starts_with("Binary files ") || line == "GIT binary patch" {
                debug::log_to_file("apply_patch binary diff", diff);
                return Err("binary patches are not supported".into());
            }
            if line.starts_with("rename from ") || line.starts_with("rename to ") {
                debug::log_to_file("apply_patch rename/copy diff", diff);
                return Err("rename/copy patches are not supported".into());
            }
            i += 1;
        }
        patches.push(patch);
    }
    Ok(patches)
}

/// Classify one hunk body line by its leading marker character.
fn parse_body_line(line: &str) -> Result<BodyLine, String> {
    if let Some(rest) = line.strip_prefix(' ') {
        Ok(BodyLine::Context(rest.to_string()))
    } else if let Some(rest) = line.strip_prefix('+') {
        Ok(BodyLine::Add(rest.to_string()))
    } else if let Some(rest) = line.strip_prefix('-') {
        Ok(BodyLine::Del(rest.to_string()))
    } else {
        Err(format!("unrecognized hunk line: {line}"))
    }
}

/// Split content into lines for hunk application. The empty element produced
/// by `str::split('\n')` when the content ends in a newline is dropped, so
/// `["a", "b"]` is two lines regardless of the final newline.
fn split_lines(content: &str) -> Vec<String> {
    let mut lines: Vec<String> = content.split('\n').map(str::to_string).collect();
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }
    lines
}

/// First index `i` where `lines[i..i+needle.len()]` equals `needle`.
fn find_subslice(lines: &[String], needle: &[&str]) -> Option<usize> {
    if needle.len() > lines.len() {
        return None;
    }
    (0..=lines.len() - needle.len()).find(|&i| {
        needle
            .iter()
            .enumerate()
            .all(|(k, want)| lines[i + k] == *want)
    })
}

/// Apply one file patch against the current working-tree contents.
///
/// Reads the file (if any), matches each hunk's old-side lines (`context` +
/// `-`) against a contiguous block, and replaces it with the new-side lines
/// (`context` + `+`). This is the reliable path that `git apply --3way` was
/// supposed to provide: the patch merges onto whatever is in the working tree
/// now, regardless of the index or object database, and a single context line
/// is enough to anchor an insertion.
fn apply_file_patch(tree: &SourceTree, patch: &FilePatch) -> Result<AppliedFile, String> {
    let rel = patch.target_rel()?;
    if is_protected(&rel) {
        return Err(format!("patch touches protected path: {rel}"));
    }
    let abs = tree
        .resolve_for_write(Path::new(&rel))
        .map_err(|e| e.to_string())?;
    if tree.is_ignored(&abs) {
        return Err(format!("path is git-ignored: {}", abs.display()));
    }

    let existing = abs.exists();
    if patch.is_new {
        if existing {
            return Err(format!(
                "refusing to create {}: file already exists",
                abs.display()
            ));
        }
        let mut lines: Vec<String> = Vec::new();
        for hunk in &patch.hunks {
            let new_side: Vec<&str> = hunk
                .lines
                .iter()
                .filter(|l| !l.is_del())
                .map(BodyLine::text)
                .collect();
            lines.extend(new_side.into_iter().map(str::to_string));
        }
        let content = if lines.is_empty() {
            String::new()
        } else {
            format!("{}\n", lines.join("\n"))
        };
        return Ok(AppliedFile {
            abs,
            content: Some(content),
        });
    }

    if !existing {
        return Err(format!(
            "cannot apply patch: {} does not exist",
            abs.display()
        ));
    }
    let content =
        std::fs::read_to_string(&abs).map_err(|e| format!("reading {}: {e}", abs.display()))?;
    let had_trailing_newline = content.ends_with('\n');
    let mut lines = split_lines(&content);

    for hunk in &patch.hunks {
        let old_side: Vec<&str> = hunk
            .lines
            .iter()
            .filter(|l| !l.is_add())
            .map(BodyLine::text)
            .collect();
        let new_side: Vec<&str> = hunk
            .lines
            .iter()
            .filter(|l| !l.is_del())
            .map(BodyLine::text)
            .collect();

        if old_side.is_empty() {
            // Pure insertion with no context (e.g. a new file). Only
            // meaningful when there is no content to anchor against.
            if lines.is_empty() {
                lines.extend(new_side.into_iter().map(str::to_string));
                continue;
            }
            return Err(format!(
                "cannot apply hunk to {}: hunk has no context but the file is not empty",
                abs.display()
            ));
        }

        let n = old_side.len();
        let Some(pos) = find_subslice(&lines, &old_side) else {
            return Err(format!(
                "cannot apply hunk to {}: context does not match",
                abs.display()
            ));
        };
        let mut applied = Vec::with_capacity(lines.len() - n + new_side.len());
        applied.extend_from_slice(&lines[..pos]);
        applied.extend(new_side.into_iter().map(str::to_string));
        applied.extend_from_slice(&lines[pos + n..]);
        lines = applied;
    }

    if patch.is_delete {
        if !lines.is_empty() {
            return Err(format!(
                "deletion patch for {} leaves content behind",
                abs.display()
            ));
        }
        return Ok(AppliedFile { abs, content: None });
    }

    let mut out = lines.join("\n");
    if had_trailing_newline && !out.is_empty() {
        out.push('\n');
    }
    Ok(AppliedFile {
        abs,
        content: Some(out),
    })
}

/// Apply a unified diff to the working tree in pure Rust.
///
/// Why not `git apply`: the `--3way` merge depends on index/HEAD blobs that
/// are frequently unavailable here (hand-composed patches carry synthetic
/// `index` hashes), and the direct fallback refuses a hunk whose insertion
/// point is not anchored by trailing context — the exact "patch does not
/// apply" failure observed when patching a file that already has uncommitted
/// edits. Applying hunks directly against the current working-tree contents
/// handles the dirty-tree case naturally and never consults the object
/// database.
///
/// Matching is all-or-nothing: every hunk of every file is first matched
/// against in-memory copies; only when the whole diff applies are any files
/// written.
fn apply_unified_diff(tree: &SourceTree, diff: &str) -> Result<(), String> {
    let patches = parse_diff(diff).map_err(|e| format!("failed to parse patch: {e}"))?;
    let mut applied = Vec::with_capacity(patches.len());
    for patch in &patches {
        applied.push(apply_file_patch(tree, patch)?);
    }
    for file in &applied {
        match &file.content {
            Some(content) => {
                if let Some(parent) = file.abs.parent() {
                    std::fs::create_dir_all(parent)
                        .map_err(|e| format!("creating parent dirs: {e}"))?;
                }
                std::fs::write(&file.abs, content)
                    .map_err(|e| format!("writing {}: {e}", file.abs.display()))?;
            }
            None => {
                std::fs::remove_file(&file.abs)
                    .map_err(|e| format!("removing {}: {e}", file.abs.display()))?;
            }
        }
    }
    Ok(())
}

/// Is the patch's change already present in the working tree? True exactly
/// when applying the reversed patch succeeds — the "change already exists,
/// stop re-patching it" signal, computed in pure Rust.
#[cfg(test)]
fn diff_already_applied(tree: &SourceTree, diff: &str) -> bool {
    let Ok(patches) = parse_diff(diff) else {
        return false;
    };
    patches
        .iter()
        .all(|p| apply_file_patch(tree, &p.reversed()).is_ok())
}

/// Extract the repo-relative path from a `--- a/…` or `+++ b/…` line,
/// stripping any trailing tab metadata (timestamps from `git diff`).
fn diff_path_from_marker(rest: &str) -> String {
    rest.split('\t').next().unwrap_or(rest).trim().to_string()
}

/// Reject diffs that touch protected paths (`.ignore`, `.git*`).
fn diff_touches_protected(diff: &str) -> Option<String> {
    for line in diff.lines() {
        for prefix in ["+++ b/", "--- a/"] {
            if let Some(rest) = line.strip_prefix(prefix) {
                let rel = diff_path_from_marker(rest);
                if is_protected(&rel) {
                    return Some(rel);
                }
            }
        }
    }
    None
}

/// Tool: apply a unified diff to the repository working tree.
pub fn builtin_apply_patch(tree: Arc<SourceTree>) -> PortableDynamicTool {
    let json = json!({
        "type": "object",
        "properties": {
        "diff": {
            "type": "string",
            "description": "Unified diff against the current working tree"
        },
        "message": {
            "type": "string",
            "description": "Optional commit message"
        }
        },
        "required": ["diff"]
    });
    let _call_back = || ();
    PortableDynamicTool::new(
        "apply_patch",
        "Apply a unified diff (git diff format) to the repository working tree. The diff is \
	 parsed and applied directly against the current working-tree contents, so it works on \
	 top of other uncommitted changes — no clean tree or `git apply` needed. Application is \
	 all-or-nothing: if any hunk fails to match, nothing is written. If `message` is given, \
	 the change is committed with that message. Diffs that touch `.ignore` or `.git*` paths \
	 are refused. Changes are local commits only — never pushed.",
        json,
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let diff = args
                    .get("diff")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'diff'"))?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if let Some(rel) = diff_touches_protected(&diff) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "diff touches protected path: {rel}"
                    )));
                }

                apply_unified_diff(&tree, &diff)
                    .map_err(|e| ToolExecutionError::provider(format!("apply failed: {e}")))?;

                let mut out = String::from("patch applied");
                if let Some(msg) = message {
                    // Stage everything so the commit captures the patch (this
                    // also covers new files and initial commits).
                    git_run(tree.root(), &["add", "-A"])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

/// Tool: write a text file inside the repository.
pub fn builtin_write_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "write_file",
        "Write a text file inside the git repository. `path` is relative to the repo root. \
	 Refused: paths outside the repo, git-ignored paths, `.ignore`, `.gitignore`, anything \
	 under `.git/`. If `message` is given, the change is committed with that message. \
	 Local commits only — never pushed.",
        json!({
            "type": "object",
            "properties": {
            "path": {
                "type": "string",
                "description": "Path relative to the repo root"
            },
            "content": {
                "type": "string",
                "description": "Full file contents"
            },
            "message": {
                "type": "string",
                "description": "Optional commit message"
            }
            },
            "required": ["path", "content"]
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let rel = args
                    .get("path")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'path'"))?
                    .to_string();
                let content = args
                    .get("content")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| {
                        ToolExecutionError::invalid_args("missing string field 'content'")
                    })?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if is_protected(&rel) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is protected: {rel}"
                    )));
                }

                // Escape/ignore checks via SourceTree (handles `..`, absolute
                // paths, symlink escapes, and ignore rules).
                let abs = tree
                    .resolve_for_write(Path::new(&rel))
                    .map_err(map_source_err)?;
                if tree.is_ignored(&abs) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is git-ignored: {}",
                        abs.display()
                    )));
                }

                if let Some(parent) = abs.parent() {
                    std::fs::create_dir_all(parent).map_err(|e| {
                        ToolExecutionError::provider(format!("creating parent dirs: {e}"))
                    })?;
                }
                std::fs::write(&abs, &content).map_err(|e| {
                    ToolExecutionError::provider(format!("writing {}: {e}", abs.display()))
                })?;

                let mut out = format!("wrote {} ({} bytes)", abs.display(), content.len());
                if let Some(msg) = message {
                    git_run(tree.root(), &["add", "--", &rel])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::source::testutil::Fixture;

    /// Make a real git repo out of `fx` with a configured identity and one
    /// initial commit, so `git status --porcelain` reflects a clean tree.
    async fn init_committed_repo(fx: &Fixture) {
        git_run(&fx.dir, &["init", "-q"]).await.expect("git init");
        git_run(&fx.dir, &["config", "user.email", "test@hanihi.local"])
            .await
            .expect("config email");
        git_run(&fx.dir, &["config", "user.name", "hanihi-test"])
            .await
            .expect("config name");
        git_run(&fx.dir, &["add", "-A"]).await.expect("git add");
        git_run(&fx.dir, &["commit", "-q", "-m", "init"])
            .await
            .expect("git commit");
    }

    /// A minimal single-file diff (with `diff --git` header) against
    /// `src/main.rs`. The synthetic `index` hashes are ignored by the
    /// pure-Rust applier.
    fn header_diff() -> &'static str {
        "diff --git a/src/main.rs b/src/main.rs\nindex 8b13789..0000000 100644\n--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1,2 @@\n fn main() {}\n+// patched\n"
    }

    #[tokio::test]
    async fn write_file_writes_new_file() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let out = tool
            .execute(serde_json::json!({
            "path": "src/new.rs",
            "content": "pub fn added() {}\n"
            }))
            .await
            .expect("write succeeds");
        let rendered = out.render();
        assert!(rendered.contains("src/new.rs"), "got: {rendered}");
        let written = std::fs::read_to_string(fx.dir.join("src/new.rs")).unwrap();
        assert_eq!(written, "pub fn added() {}\n");
    }

    #[tokio::test]
    async fn write_file_refuses_protected_and_ignored() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());

        let err = tool
            .execute(serde_json::json!({
            "path": ".ignore",
            "content": "junk\n"
            }))
            .await
            .expect_err("protected path must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");

        let err = tool
            .execute(serde_json::json!({
            "path": "target/debug/junk.rs",
            "content": "junk\n"
            }))
            .await
            .expect_err("ignored path must fail");
        assert!(err.to_string().contains("git-ignored"), "got: {err}");
    }

    #[tokio::test]
    async fn write_file_refuses_escapes() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let name = format!("hanihi-write-outside-{}", uuid::Uuid::new_v4());
        let err = tool
            .execute(serde_json::json!({
            "path": format!("../{name}"),
            "content": "x"
            }))
            .await
            .expect_err("escape must fail");
        assert!(err.to_string().contains("escapes"), "got: {err}");
    }

    #[tokio::test]
    async fn apply_patch_applies_and_commits() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;
        let tool = builtin_apply_patch(fx.tree());
        let out = tool
            .execute(serde_json::json!({
            "diff": header_diff(),
            "message": "test patch"
            }))
            .await
            .unwrap_or_else(|e| panic!("apply failed: {e}"));
        let rendered = out.render();
        assert!(rendered.contains("patch applied"), "got: {rendered}");
        assert!(rendered.contains("committed"), "got: {rendered}");
        let main = std::fs::read_to_string(fx.dir.join("src/main.rs")).unwrap();
        assert!(main.contains("// patched"));

        // Committed: working tree must be clean.
        let (stdout, _) = git_run(&fx.dir, &["status", "--porcelain"]).await.unwrap();
        assert_eq!(stdout.trim(), "", "expected clean tree, got: {stdout}");
    }

    #[tokio::test]
    async fn apply_patch_works_on_dirty_tree() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;

        // The case plain `git apply` refused: an uncommitted edit already
        // sits in the target file and the hunk has no trailing context. The
        // applier must insert the patch on top of the local edit instead of
        // refusing.
        std::fs::write(fx.dir.join("src/main.rs"), "fn main() {}\n// local\n").unwrap();

        let tool = builtin_apply_patch(fx.tree());
        tool.execute(serde_json::json!({ "diff": header_diff() }))
            .await
            .unwrap_or_else(|e| panic!("apply over dirty tree must succeed: {e}"));

        let main = std::fs::read_to_string(fx.dir.join("src/main.rs")).unwrap();
        assert!(main.contains("// patched"), "got: {main}");
        // The pre-existing uncommitted edit is preserved alongside the patch.
        assert!(main.contains("// local"), "got: {main}");
    }

    #[tokio::test]
    async fn apply_patch_adds_new_file_on_clean_tree() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;

        // Adding a brand-new file (not already present) must work.
        let add = "diff --git a/src/extra.rs b/src/extra.rs\nnew file mode 100644\n--- /dev/null\n+++ b/src/extra.rs\n@@ -0,0 +1 @@\n+pub fn extra() {}\n";

        let tool = builtin_apply_patch(fx.tree());
        tool.execute(serde_json::json!({ "diff": add }))
            .await
            .unwrap_or_else(|e| panic!("apply must succeed adding a new file: {e}"));

        let extra = std::fs::read_to_string(fx.dir.join("src/extra.rs")).unwrap();
        assert_eq!(extra, "pub fn extra() {}\n");
    }

    #[tokio::test]
    async fn apply_patch_rejects_bad_diff_and_protected_paths() {
        let fx = Fixture::new();
        let tool = builtin_apply_patch(fx.tree());

        let err = tool
            .execute(serde_json::json!({ "diff": "not a diff at all" }))
            .await
            .expect_err("bad diff must fail");
        assert!(err.to_string().contains("failed"), "got: {err}");

        let err = tool
	    .execute(serde_json::json!({ "diff": "--- a/.ignore\n+++ b/.ignore\n@@ -1 +1 @@\n-x\n+y\n" }))
	    .await
	    .expect_err("protected diff must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");
    }

    #[test]
    fn protected_path_detection() {
        assert!(is_protected(".ignore"));
        assert!(is_protected(".gitignore"));
        assert!(is_protected(".git/config"));
        assert!(is_protected(".git"));
        assert!(!is_protected("src/main.rs"));
        assert!(!is_protected("docs/.ignore.md"));
    }

    #[test]
    fn diff_protected_scan() {
        assert_eq!(
            diff_touches_protected("--- a/src/main.rs\n+++ b/src/main.rs\n"),
            None
        );
        assert_eq!(
            diff_touches_protected("+++ b/.ignore\n"),
            Some(".ignore".to_string())
        );
        // Path with tab (git diff metadata) is still caught.
        assert_eq!(
            diff_touches_protected("+++ b/.git/config\t2026-01-01\n"),
            Some(".git/config".to_string())
        );
    }

    #[tokio::test]
    async fn diff_already_applied_detects_existing_change() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;
        let tree = fx.tree();

        // Nothing applied yet: the change is not present.
        assert!(!diff_already_applied(&tree, header_diff()));

        // Apply it, then the change is present.
        apply_unified_diff(&tree, header_diff()).expect("apply");
        assert!(diff_already_applied(&tree, header_diff()));
    }
}

//! # hanihi-cli
//!
//! REPL front-end for the agent harness: reedline line editor on top of
//! [`hanihi_core::Agent`]. Supports sessions (`--session` / `--new-session`),
//! one-shot turns (`--once`), and MCP stdio servers.

mod highlight;
mod ui;

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use crate::highlight::MonoHighlighter;
use clap::Parser;
use hanihi_core::agent::Agent;
use hanihi_core::error::AgentError;
use hanihi_core::session::SessionManager;
use hanihi_core::{
    McpClient, SourceTree, StreamEvent, builtin_apply_patch, builtin_get_time, builtin_grep,
    builtin_list_dir, builtin_read_file, builtin_read_session_log, builtin_run_command,
    builtin_run_command_write, builtin_write_file, connect_chat_model_with_prompt, debug,
};
use nu_ansi_term::Color;
use reedline::{DefaultPrompt, FileBackedHistory, Reedline, Signal};
use rig::completion::CompletionModel;
use tracing_subscriber::EnvFilter;

pub use hanihi_core::agent::{TurnSummary, connect_chat_model};

use crate::ui::{print_coloured, println_coloured};

const DEFAULT_WORKING_DIR: &str = "./working";
/// Default cap on model turns per request. Effectively unlimited: a sane
/// upper bound so runaway tool-call loops still terminate, but far above any
/// realistic working session.
const DEFAULT_MAX_TURNS: usize = 10;
/// Default cap on model turns in task mode (long-horizon self-improvement).
const TASK_MAX_TURNS: usize = 10;

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
        long,
        env = "LLM_BASE_URL",
        default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/mcp-echo-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,

    /// Register write tools (apply_patch, write_file) — enables editing the
    /// enclosing repository. Off by default; analysis and build tools are
    /// always on.
    #[arg(long)]
    write: bool,

    /// Run a single long-horizon turn with the task-mode system prompt
    /// (workflow gates: fmt → test → build → clippy → commit). Takes
    /// precedence over --once.
    #[arg(long, value_name = "PROMPT")]
    task: Option<String>,

    /// Maximum model turns per request (default: 1000; task mode: 1000).
    #[arg(long)]
    max_turns: Option<usize>,

    /// Append this text to the system prompt. Repeatable. When used with an
    /// existing session, the appended text is persisted to the session so it
    /// applies on future resumes too.
    #[arg(long = "prompt", value_name = "TEXT")]
    prompt_append: Vec<String>,

    /// Append the content of this file to the system prompt. Repeatable.
    /// When used with an existing session, the appended content is persisted
    /// to the session so it applies on future resumes too.
    #[arg(long = "prompt-file", value_name = "PATH")]
    prompt_files: Vec<PathBuf>,

    /// Replace the entire system prompt with the additions (no base prompt
    /// is prepended). For use with --session to rewrite the stored prompt,
    /// or with --new-session to override the default. Mutually exclusive
    /// with --prompt/--prompt-file append semantics (see below).
    #[arg(long)]
    new_prompt: bool,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
        .trim_start_matches("https://")
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
        .trim_start_matches("api-")
        .split('.')
        .next()
        .unwrap_or("unknown")
}

/// Read the given prompt files and return their concatenated contents.
fn read_prompt_files(paths: &[PathBuf]) -> Result<String, AgentError> {
    let mut out = String::new();
    for path in paths {
        let content = fs::read_to_string(path)?;
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(&content);
    }
    Ok(out)
}

/// Read a single file's contents for use as a prompt, resolved against the
/// given base directory when the path is not absolute.
fn read_prompt_file(base: &Path, path: &str) -> Result<String, AgentError> {
    let resolved = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        base.join(path)
    };
    if !resolved.is_file() {
        return Err(AgentError::Io(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("no such file: {}", resolved.display()),
        )));
    }
    fs::read_to_string(&resolved).map_err(AgentError::Io)
}

/// Concatenate the explicit additions (`--prompt` strings and the contents
/// of `--prompt-file` files) into one block.
fn collect_extras(
    prompt_appends: &[String],
    prompt_files: &[PathBuf],
) -> Result<String, AgentError> {
    let file_text = read_prompt_files(prompt_files)?;
    let mut parts: Vec<String> = Vec::new();
    parts.extend(prompt_appends.iter().cloned());
    if !file_text.is_empty() {
        parts.push(file_text);
    }
    Ok(parts.join("\n\n"))
}

/// Whether any explicit prompt additions were supplied.
fn has_extras(prompt_appends: &[String], prompt_files: &[PathBuf]) -> bool {
    !prompt_appends.is_empty() || !prompt_files.is_empty()
}

/// Read the system prompt stored in an existing session's session.json.
fn stored_session_prompt(working_dir: &std::path::Path, session_name: &str) -> Option<String> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read_to_string(meta_path).ok()?;
    let meta: serde_json::Value = serde_json::from_str(&bytes).ok()?;
    meta.get("system_prompt")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Persist a system prompt into an existing session's session.json. Reads
/// the file, updates the field, writes it back.
fn write_session_prompt(
    working_dir: &std::path::Path,
    session_name: &str,
    prompt: &str,
) -> Result<(), AgentError> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read(&meta_path).map_err(AgentError::Io)?;
    let mut meta: serde_json::Value = serde_json::from_slice(&bytes).map_err(AgentError::Json)?;
    meta["system_prompt"] = serde_json::Value::String(prompt.to_string());
    fs::write(&meta_path, serde_json::to_string_pretty(&meta)?).map_err(AgentError::Io)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let api_key = args
        .api_key
        .filter(|k| !k.is_empty())
        .ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
        args.working_dir.clone()
    } else {
        std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    let task_mode = args.task.is_some();
    let base_prompt: &str = if task_mode {
        hanihi_core::agent::TASK_SYSTEM_PROMPT
    } else {
        hanihi_core::agent::DEFAULT_SYSTEM_PROMPT
    };

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
        (name.clone(), true)
    } else {
        let name = args.session.clone();
        // Auto-create default-session if it doesn't exist.
        let is_new = name == "default-session" && !mgr.exists(&name);
        (name, is_new)
    };

    let had_extras = has_extras(&args.prompt_append, &args.prompt_files);

    // Resolve the system prompt this invocation will use, and whether it
    // must be persisted back to the session's metadata.
    //
    // Prompt resolution rules:
    //  - `--new-prompt` on any session: the additions (collected from
    //    --prompt / --prompt-file) become the ENTIRE prompt. On an existing
    //    session this replaces and persists the stored prompt.
    //  - Otherwise `--prompt` / `--prompt-file` append to the base prompt
    //    (new session) or to the stored prompt (existing session), and the
    //    appended result is persisted so it survives a resume.
    //  - With no additions at all, the existing stored prompt is used
    //    unchanged (or the base prompt for a fresh session).
    let (session_prompt, do_persist) = if args.new_prompt {
        // Replace/set the entire prompt from the additions only.
        let prompt = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let effective = if prompt.trim().is_empty() {
            // --new-prompt with nothing supplied: use base as the new prompt.
            base_prompt.to_string()
        } else {
            prompt
        };
        if is_new {
            (effective, false) // creation persists it
        } else {
            (effective, true) // replace + persist the stored prompt
        }
    } else if is_new {
        // Fresh session: base + any appends. persisted by creation.
        let prompt = if had_extras {
            let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
            format!("{base_prompt}\n\n{extras}")
        } else {
            base_prompt.to_string()
        };
        (prompt, false)
    } else if had_extras {
        // Existing session with appends: stored + extras, persisted.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let prompt = format!("{stored}\n\n{extras}");
        (prompt, true)
    } else {
        // Existing session, no additions: use stored prompt unchanged.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        (stored, false)
    };

    // Create or open the session.
    if is_new {
        if session_name == "default-session" {
            mgr.create_default(&args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("auto-created session 'default-session'");
        } else {
            mgr.create(&session_name, &args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("created session '{session_name}'");
        }
    } else {
        mgr.open(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        if do_persist {
            write_session_prompt(&working_dir, &session_name, &session_prompt)?;
            if args.new_prompt {
                println!("session '{session_name}' system prompt replaced");
            } else {
                println!("session '{session_name}' system prompt extended");
            }
        }
    }

    // Build the agent with the resolved system prompt.
    let mut agent = connect_chat_model_with_prompt(
        args.base_url.clone(),
        api_key.clone(),
        args.model.clone(),
        &session_prompt,
    )?;
    agent.set_max_turns(args.max_turns.unwrap_or(if task_mode {
        TASK_MAX_TURNS
    } else {
        DEFAULT_MAX_TURNS
    }));
    agent.add_tool(builtin_get_time());

    // Source-tree tools: read/list/grep/run-command over the enclosing git
    // repository, plus a window into this session's own event log. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see. Write tools
    // (apply_patch, write_file) are registered only with --write.
    match SourceTree::open() {
        Ok(tree) => {
            let tree = Arc::new(tree);
            let traces_dir = working_dir.join("traces").join(&session_name);
            let log_path = working_dir
                .join("sessions")
                .join(&session_name)
                .join("events.jsonl");
            agent.add_tool(builtin_read_file(tree.clone()));
            agent.add_tool(builtin_list_dir(tree.clone()));
            agent.add_tool(builtin_grep(tree.clone()));
            if args.write {
                agent.add_tool(builtin_run_command_write(tree.clone(), traces_dir));
            } else {
                agent.add_tool(builtin_run_command(tree.clone(), traces_dir));
            }
            agent.add_tool(builtin_read_session_log(log_path));
            if args.write {
                agent.add_tool(builtin_apply_patch(tree.clone()));
                agent.add_tool(builtin_write_file(tree));
            }
        }
        Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
        debug::log_to_file("command from args.mcp_commands: ", command);
        let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
        let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
            name: "<mcp>".into(),
            message: "empty --mcp-command".into(),
        })?;
        let client = McpClient::connect_stdio(program, rest).await?;
        let tools = client.tool_defs().await?;
        let count = tools.len();
        for tool in tools {
            agent.add_tool(tool);
        }
        println!("attached MCP server '{program}': {count} tool(s)");
    }

    // Get a mutable reference to the open session so we can read its turn
    // count for the "session renewed" metadata below.
    let session = mgr
        .open(&session_name)
        .map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    // Replay prior turns from the event log so the agent remembers
    // previous conversations in this session.
    let mut prior_turns = None;
    match session.replay_history() {
        Ok(history) if !history.is_empty() => {
            let msg_count = history.len();
            agent.set_history(history);
            println!("replayed {msg_count} messages from prior session");
        }
        Ok(_) => {} // empty history, nothing to replay
        Err(e) => {
            tracing::warn!("failed to replay session history: {e}");
        }
    }
    // How many turns has this session accumulated so far (including from
    // prior sessions)? Use the session's own counter; it is monotonically
    // increasing across restarts of the same session name.
    if let Ok(turns) = session.total_turns() {
        prior_turns = Some(turns);
    }

    println!(
        "agent ready: model={} tools={} session='{session_name}' max_turns={}{}",
        args.model,
        agent.tool_count(),
        agent.max_turns(),
        if args.write {
            " (write tools enabled)"
        } else {
            ""
        },
    );
    if let Some(t) = prior_turns {
        println!(
            "session '{}' renewed: total turns so far = {t}",
            session_name
        );
    }
    println!("system prompt: {} bytes", session_prompt.len());

    let prompt = args.task.clone().or_else(|| args.once.clone());
    if let Some(prompt) = prompt {
        let mut rx = session
            .run_streaming(&mut agent, provider, &args.model, &prompt)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        while let Some(event) = rx.recv().await {
            match event {
                StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                StreamEvent::ToolCallArgs { .. } => {}
                StreamEvent::ToolCallReady { .. } => {}
                StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                StreamEvent::CompletionRequest { .. } | StreamEvent::CompletionResponse { .. } => {}
                StreamEvent::TurnComplete { summary } => {
                    println!();
                    println_coloured!(
                        "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                        session.turn,
                        summary.tool_calls,
                        summary.usage.input_tokens,
                        summary.usage.output_tokens,
                        agent.max_turns()
                    );
                    agent.set_history(summary.final_history);
                    break;
                }
                StreamEvent::Error { message } => {
                    eprintln!();
                    eprintln!("error: {message}");
                    break;
                }
            }
        }
        mgr.close(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        return Ok(());
    }

    let cwd = std::env::current_dir().map_err(AgentError::Io)?;
    repl(session, agent, provider, &args.model, &cwd, &working_dir).await?;

    mgr.close(&session_name)
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Render the per-turn completion footer shown after (and by /session for) a turn.
fn turn_footer(
    model: &str,
    turn: u64,
    tool_calls: usize,
    tokens_in: u64,
    tokens_out: u64,
    max_turns: usize,
) -> String {
    format!(
        "[model: {model} turn {turn} | tool calls: {tool_calls} | tokens: {tokens_in} in / {tokens_out} out | max_turns: {max_turns}]"
    )
}

/// Interactive readline loop.
async fn repl<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
    cwd: &Path,
    working_dir: &Path,
) -> Result<(), AgentError> {
    let history_path = session.root().join("history.txt");
    let history: Box<dyn reedline::History> =
        match FileBackedHistory::with_file(10_000, history_path) {
            Ok(h) => Box::new(h),
            Err(e) => {
                eprintln!("history file disabled: {e}");
                Box::new(FileBackedHistory::new(10_000).expect("in-memory history"))
            }
        };
    let edit_mode = reedline::Emacs::default();
    let mut editor = Reedline::create()
        .with_edit_mode(Box::new(edit_mode))
        .with_history(history)
        .with_highlighter(Box::new(MonoHighlighter::new(Color::Cyan)));
    let prompt = DefaultPrompt::default();
    let mut last_summary: Option<TurnSummary> = None;
    loop {
        match editor.read_line(&prompt) {
            Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
                let line = line.trim().to_string();
                match line.as_str() {
                    "" => continue,
                    "/quit" | "/exit" => break,
                    "/help" => {
                        println!(
                            "commands: /help /tools /clear /session /file /quit — anything else is sent to the model"
                        );
                        continue;
                    }
                    "/tools" => {
                        for def in agent.tool_definitions() {
                            println!("- {}: {}", def.name, def.description);
                        }
                        continue;
                    }
                    "/clear" => {
                        agent.clear_history();
                        println!("history cleared");
                        continue;
                    }
                    "/session" => {
                        println!(
                            "session: '{}' (id={}) turn={} max_turns={}",
                            session.name,
                            session.id,
                            session.turn,
                            agent.max_turns()
                        );
                        if let Some(s) = &last_summary {
                            println!(
                                "{}",
                                turn_footer(
                                    session.model.as_str(),
                                    session.turn,
                                    s.tool_calls,
                                    s.usage.input_tokens,
                                    s.usage.output_tokens,
                                    agent.max_turns(),
                                )
                            );
                        } else {
                            println!("No TurnSummary");
                        }
                        continue;
                    }
                    _ => {}
                }

                // Handle `/file <PATH>`: read the file's contents relative to
                // the working directory (or absolute) and use it as the prompt.
                // Only a single line can be typed at the REPL prompt, so this
                // lets multi-line content (a prompt, a plan, code) be loaded
                // from disk and sent to the model in one go.
                if let Some(rest) = line.strip_prefix("/file ") {
                    let path = rest.trim();
                    if path.is_empty() {
                        eprintln!("/file requires a path");
                        continue;
                    }
                    let content = match read_prompt_file(working_dir, path) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("error reading '{path}': {e}");
                            continue;
                        }
                    };
                    if content.trim().is_empty() {
                        eprintln!("/file '{path}' is empty");
                        continue;
                    }
                    println!(
                        "using contents of '{}' ({}, {} bytes) as prompt",
                        path,
                        cwd.display(),
                        content.len()
                    );
                    last_summary =
                        run_turn(session, &mut agent, provider, model_name, &content).await;
                    continue;
                }

                last_summary = run_turn(session, &mut agent, provider, model_name, &line).await;
            }
            Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
            Ok(Signal::CtrlD) => break,
            Ok(_) => continue,
            Err(e) => {
                eprintln!("readline error: {e}");
                break;
            }
        }
    }

    // Sync history to disk before shutting down.
    if let Err(e) = editor.sync_history() {
        eprintln!("warning: failed to sync history: {e}");
    }
    Ok(())
}

/// Run a single turn with the given prompt and stream the model's output.
async fn run_turn<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    agent: &mut Agent<M>,
    provider: &str,
    model_name: &str,
    prompt: &str,
) -> Option<TurnSummary> {
    match session
        .run_streaming(agent, provider, model_name, prompt)
        .await
    {
        Ok(mut rx) => {
            while let Some(event) = rx.recv().await {
                match event {
                    StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                    StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                    StreamEvent::ToolCallArgs { .. } => {}
                    StreamEvent::ToolCallReady { .. } => {}
                    StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                    StreamEvent::CompletionRequest { .. }
                    | StreamEvent::CompletionResponse { .. } => {}
                    StreamEvent::TurnComplete { summary } => {
                        println!();
                        println_coloured!(
                            "[model: {} turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                            session.model,
                            session.turn,
                            summary.tool_calls,
                            summary.usage.input_tokens,
                            summary.usage.output_tokens,
                            agent.max_turns()
                        );
                        // TODO: Do I need this `clone`?
                        agent.set_history(summary.final_history.clone());
                        return Some(summary);
                    }
                    StreamEvent::Error { message } => {
                        eprintln!();
                        eprintln!("error: {message}");
                        return None;
                    }
                }
            }
            None
        }
        Err(e) => {
            eprintln!("error: {e}");
            None
        }
    }
}

